INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (1000125, '6.1', 'Upon completion of the risk analysis process, operators should determine the appropriate mitigation measures for both critical and non-critical facilities.', NULL, 'Facility Security Measures', 'Introduction', NULL, NULL, 'SET.20190617.130513', NULL, NULL, NULL, 33, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (1000126, '6.2', 'Pipeline operators should develop and implement baseline security measures at all of their facilities.
Operators should develop and implement both baseline and enhanced security measures at each of their critical facilities.', 'Table 1 identifies the baseline and enhanced security measures for operators to implement at appropriate pipeline facilities. Recurring actions are summarized in Appendix A.', 'Facility Security Measures', 'Baseline and Enhanced Security Measures', NULL, NULL, 'SET.20190617.130513', NULL, NULL, NULL, 33, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (1000127, '6.3', 'Operators should develop, document, and implement site-specific security measures for each of their critical facilities. These measures should be tailored explicitly for each facility and address specific actions to be taken in response to pertinent NTAS Bulletins or Alerts. On a periodic basis, not to exceed 18 months, these site-specific security measures should be reviewed and updated as necessary.', NULL, 'Facility Security Measures', 'Site-Specific Security Measures', NULL, NULL, 'SET.20190617.130513', NULL, NULL, NULL, 33, NULL)
INSERT INTO [dbo].[NEW_REQUIREMENT] ([Requirement_Id], [Requirement_Title], [Requirement_Text], [Supplemental_Info], [Standard_Category], [Standard_Sub_Category], [Weight], [Implementation_Recommendations], [Original_Set_Name], [NCSF_Cat_Id], [NCSF_Number], [Ranking], [Question_Group_Heading_Id], [ExaminationApproach]) VALUES (1000128, '6.2.1', 'Employ measures to impede unauthorized access to facilities.', '<style>* {font-family: ''Segoe UI'', Tahoma, Geneva, Verdana, sans-serif;}table {border-collapse: collapse; margin: 3rem;} table td {border: 1px solid #000; padding: .5rem; vertical-align: top;} .brown {text-align: center; color: #fff; background-color: #653300; font-weight: 700; text-transform: uppercase;} .gold {text-align: center; color: #000; background-color: #cc9a00; font-weight: 700;} .vanilla {text-align: center; color: #000; background-color: #ffde82; font-weight: 700;} .sideways {vertical-align: middle !important; max-width: 5rem;} .sideways div {display: block; white-space: nowrap; font-style: oblique; transform: rotate(270deg);  -webkit-transform: rotate(270deg); -moz-transform: rotate(270deg); -ms-transform: rotate(270deg); -o-transform: rotate(270deg); } .center { text-align: center;} .supplementalHighlight{background-color: yellow;}</style>
<!--Table on Page 11-->
<table>

	<tbody><tr class="brown">
        <td style="width: 10%"></td>
        <td style="width: 45%">Baseline Security Measures</td>
        <td style="width: 45%">Enhanced Security Measures</td>
    </tr>

    <tr>
        <td rowspan="14" class="sideways gold" style="width: 10%">
            <div>Physical Security <br>and Access Control</div>
        </td>
        <td colspan="2" class="center gold">
            Fencing/Barriers
        </td>
    </tr>

    <tr>
        <td> <mark class="supplementalHighlight">Employ measures to impede unauthorized access to facilities.</mark></td>
        <td>Create a security perimeter that impedes unauthorized vehicles from entering the facility perimeter or critical areas by installing and maintaining barriers(e.g., fences, bollards, jersey barriers, or equivalent.)</td>
    </tr>
	
	<tr>
		<td>Maintain fences, if used, without gaps around gates or underneath the fence line.</td>
		<td></td>
	</tr>
	
	<tr>
		<td>Ensure that there is a clear zone for several feet on either side of the fence, free of obstructions, vegetation, or objects that could be used for concealment or to scale the fence.</td>
		<td></td>
	</tr>
	
    <tr><td colspan="2" class="center gold"></td></tr></tbody></table><br>', 'Facility Security Measures', 'Baseline and Enhanced Security Measures', NULL, NULL, 'SET.20190617.130513', NULL, NULL, NULL, 33, NULL)
